// Declaración de paquete (primera línea del fichero)
package com.empresa.proyecto;

// Importar todo el contenido de un paquete externo
import otro.paquete.*;

// Declaración y asignación separadas
[Visibilidad] tipo nombreVariable1;
nombreVariable1 = valor1;

// Declaración y asignación en la misma línea
[Visibilidad] tipo nombreVariable2 = valor2;

// Declaración de constante
[Visibilidad] static final tipo NOMBRE_CONSTANTE = valor;

// Ejemplo concreto
public static final int MAX_INTENTOS = 3;

// Conversión implícita (widening)
byte b = 1;
short s = b;
int i = s;
long l = i;
float f = l;
double d = f;

// Conversión explícita (narrowing)
int i = 127;
byte b = (byte) i;  // b almacena 127

int i2 = 128;
byte b2 = (byte) i2; // b2 almacena -128 (desbordamiento)

// Formas de declarar un String
String a = "prueba de string";
String b = a;  // b apunta al mismo objeto que a

// Autoboxing: primitivo -> envoltorio (automático)
Integer a = 11, b = 20;

// Unboxing: envoltorio -> primitivo (automático)
int c = b - a;  // c = 9
